contracts/Bridge.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.28;

import {ECDSA} from "@openzeppelin/contracts/utils/cryptography/ECDSA.sol";
import {MessageHashUtils} from "@openzeppelin/contracts/utils/cryptography/MessageHashUtils.sol";
import {Ownable} from "@openzeppelin/contracts/access/Ownable.sol";
import {Token} from "./Token.sol";

/// @title LBRY Bridge
/// @notice Custodial 1:1 bridge between native LBC (LBRY chain) and wLBC (this chain).
///
///         Wrap  (LBC -> wLBC): a user deposits native LBC to the custodial LBRY
///         address off-chain. A trusted signer (the owner) verifies the deposit
///         and produces a signature; anyone can relay it here to mint wLBC 1:1.
///         `processed[lbcTxid]` makes each LBC deposit redeemable exactly once,
///         so the mint is idempotent and replay-safe on-chain — no database.
///
///         Unwrap (wLBC -> LBC): a user burns wLBC here and names the LBRY
///         address to receive native LBC. The burn is recorded on-chain via the
///         `Unwrap` event; an off-chain worker reads it (by the emitting tx) and
///         broadcasts the native LBC payout.
///
/// @dev Trust model (MVP): a single owner key is the mint authority and the
///      off-chain custodian. This is fully custodial and trusted. The authority
///      is a distinct `signer` slot (not raw `owner()`) so it can later move to a
///      multisig/threshold signer without changing this interface.
contract Bridge is Ownable {
    using ECDSA for bytes32;
    using MessageHashUtils for bytes32;

    /// @notice The wLBC token this bridge mints and burns.
    Token public immutable token;

    /// @notice Key authorised to sign wrap approvals. Starts as the deployer.
    address public signer;

    /// @notice LBC deposit txids that have already been minted. The on-chain ledger.
    mapping(bytes32 => bool) public processed;

    /// @notice Monotonic id for unwrap requests, so each burn is uniquely referable.
    uint256 public unwrapCount;

    event SignerUpdated(address indexed previousSigner, address indexed newSigner);

    /// @param to        recipient of the minted wLBC
    /// @param amount    wLBC minted (1:1 with deposited LBC, 8 decimals)
    /// @param lbcTxid   the native LBC deposit transaction id that funded this mint
    event Wrapped(address indexed to, uint256 amount, bytes32 indexed lbcTxid);

    /// @param id           sequential unwrap id
    /// @param from         address that burned wLBC
    /// @param amount       wLBC burned (native LBC to be paid out 1:1)
    /// @param lbcAddress   destination LBRY address for the native LBC payout
    event Unwrap(uint256 indexed id, address indexed from, uint256 amount, string lbcAddress);

    error AlreadyProcessed(bytes32 lbcTxid);
    error InvalidSignature();
    error ZeroAmount();
    error ZeroAddress();
    error EmptyLbcAddress();

    constructor(address _token) Ownable(msg.sender) {
        if (_token == address(0)) revert ZeroAddress();
        token = Token(_token);
        signer = msg.sender;
    }

    /// @notice Rotate the wrap-approval signer (mint authority).
    function setSigner(address newSigner) external onlyOwner {
        if (newSigner == address(0)) revert ZeroAddress();
        emit SignerUpdated(signer, newSigner);
        signer = newSigner;
    }

    /// @notice The exact message a `signer` must sign to authorise a wrap.
    /// @dev Binds the mint to this specific chain and this specific bridge so a
    ///      signature can't be replayed on another deployment. Exposed for the
    ///      off-chain signer/relayer to reproduce.
    function wrapMessageHash(
        address to,
        uint256 amount,
        bytes32 lbcTxid
    ) public view returns (bytes32) {
        return keccak256(
            abi.encodePacked(block.chainid, address(this), to, amount, lbcTxid)
        );
    }

    /// @notice Mint wLBC 1:1 against a verified native-LBC deposit.
    /// @dev Permissionless to call — security comes from the signature and the
    ///      `processed` guard, so anyone (typically the user or a relayer) can
    ///      submit a valid approval. Reverts if `lbcTxid` was already redeemed.
    /// @param to         recipient of the wLBC
    /// @param amount     amount to mint (must equal the deposited LBC, 8 decimals)
    /// @param lbcTxid    the native LBC deposit txid backing this mint
    /// @param signature  `signer`'s signature over `wrapMessageHash(...)`
    function wrap(
        address to,
        uint256 amount,
        bytes32 lbcTxid,
        bytes calldata signature
    ) external {
        if (to == address(0)) revert ZeroAddress();
        if (amount == 0) revert ZeroAmount();
        if (processed[lbcTxid]) revert AlreadyProcessed(lbcTxid);

        bytes32 digest = wrapMessageHash(to, amount, lbcTxid).toEthSignedMessageHash();
        if (digest.recover(signature) != signer) revert InvalidSignature();

        processed[lbcTxid] = true;
        token.mint(to, amount);

        emit Wrapped(to, amount, lbcTxid);
    }

    /// @notice Burn wLBC to redeem native LBC on the LBRY chain.
    /// @dev Records the request on-chain via `Unwrap`; the off-chain custodian
    ///      watches for it (looked up by this tx's hash) and pays out native LBC.
    ///      No signature needed — burning the caller's own balance is the auth.
    /// @param amount      amount of wLBC to burn (native LBC paid out 1:1)
    /// @param lbcAddress  destination LBRY address for the payout
    function unwrap(uint256 amount, string calldata lbcAddress) external {
        if (amount == 0) revert ZeroAmount();
        if (bytes(lbcAddress).length == 0) revert EmptyLbcAddress();

        token.burn(msg.sender, amount);

        uint256 id = unwrapCount++;
        emit Unwrap(id, msg.sender, amount, lbcAddress);
    }
}

contracts/MockERC20.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.10;

/**
 * @title MockERC20
 * @dev Mock ERC20 token for testing purposes
 */
contract MockERC20 {
    string public name;
    string public symbol;
    uint8 public decimals;
    uint256 public totalSupply;

    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    event Transfer(address indexed from, address indexed to, uint256 value);
    event Approval(address indexed owner, address indexed spender, uint256 value);

    constructor(string memory _name, string memory _symbol, uint8 _decimals) {
        name = _name;
        symbol = _symbol;
        decimals = _decimals;
    }

    function mint(address to, uint256 amount) external {
        totalSupply += amount;
        balanceOf[to] += amount;
        emit Transfer(address(0), to, amount);
    }

    function transfer(address to, uint256 amount) external returns (bool) {
        require(balanceOf[msg.sender] >= amount, "Insufficient balance");
        balanceOf[msg.sender] -= amount;
        balanceOf[to] += amount;
        emit Transfer(msg.sender, to, amount);
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(balanceOf[from] >= amount, "Insufficient balance");
        require(allowance[from][msg.sender] >= amount, "Insufficient allowance");

        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        allowance[from][msg.sender] -= amount;

        emit Transfer(from, to, amount);
        return true;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        emit Approval(msg.sender, spender, amount);
        return true;
    }
}

contracts/Sale.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.10;

/**
 * @title IERC20 Interface
 * @dev Interface for ERC20 token interactions
 */
interface IERC20 {
    function totalSupply() external view returns (uint256);
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function allowance(address owner, address spender) external view returns (uint256);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
}

/**
 * @title Sale
 * @dev Contract for handling LBRY credit sales with USDC payment
 */
contract Sale {
    // USDC token contract
    IERC20 public immutable usdc;

    // Contract owner
    address public owner;

    // Price of LBRY credits in USDC (with 6 decimals for USDC)
    uint256 public lbryPriceInUsdc;

    // Reentrancy guard
    bool private locked;

    // Mapping of order ID to purchase details
    mapping(bytes32 => PurchaseOrder) public orders;

    // Mapping of user address to their LBRY address
    mapping(address => string) public userLbryAddresses;

    // Array to track all order IDs
    bytes32[] public allOrderIds;

    struct PurchaseOrder {
        address buyer;
        uint256 usdcAmount;
        uint256 lbryAmount;
        string lbryAddress;
        bool fulfilled;
        string lbryTxHash;
        uint256 timestamp;
    }

    // Events
    event Purchase(
        bytes32 indexed orderId,
        address indexed buyer,
        uint256 usdcAmount,
        uint256 lbryAmount,
        string lbryAddress,
        uint256 timestamp
    );

    event OrderFulfilled(
        bytes32 indexed orderId,
        string lbryTxHash,
        uint256 timestamp
    );

    event PriceUpdated(
        uint256 oldPrice,
        uint256 newPrice,
        uint256 timestamp
    );

    event LbryAddressUpdated(
        address indexed user,
        string oldAddress,
        string newAddress
    );

    modifier onlyOwner() {
        require(msg.sender == owner, "Only owner can call this function");
        _;
    }

    modifier nonReentrant() {
        require(!locked, "Reentrant call");
        locked = true;
        _;
        locked = false;
    }

    constructor(
        address _usdcToken,
        uint256 _initialPriceInUsdc,
        address _owner
    ) {
        require(_usdcToken != address(0), "Invalid USDC token address");
        require(_initialPriceInUsdc > 0, "Price must be greater than 0");
        require(_owner != address(0), "Invalid owner address");

        usdc = IERC20(_usdcToken);
        lbryPriceInUsdc = _initialPriceInUsdc;
        owner = _owner;
    }

    /**
     * @dev Buy LBRY credits with USDC
     * @param _usdcAmount Amount of USDC to spend (with 6 decimals)
     * @param _lbryAddress LBRY address where credits will be sent
     */
    function buy(uint256 _usdcAmount, string calldata _lbryAddress) 
        external 
        nonReentrant 
        returns (bytes32 orderId) 
    {
        require(_usdcAmount > 0, "Amount must be greater than 0");
        require(bytes(_lbryAddress).length > 0, "LBRY address cannot be empty");
        require(lbryPriceInUsdc > 0, "Price not set");

        // Calculate LBRY amount (assuming LBRY has 8 decimals)
        uint256 lbryAmount = (_usdcAmount * 1e8) / lbryPriceInUsdc;
        require(lbryAmount > 0, "Calculated LBRY amount is 0");

        // Generate unique order ID
        orderId = keccak256(abi.encodePacked(
            msg.sender,
            _usdcAmount,
            _lbryAddress,
            block.timestamp,
            block.difficulty
        ));

        // Ensure order ID is unique
        require(orders[orderId].buyer == address(0), "Order ID collision");

        // Transfer USDC from buyer to contract
        require(
            usdc.transferFrom(msg.sender, address(this), _usdcAmount),
            "USDC transfer failed"
        );

        // Store order details
        orders[orderId] = PurchaseOrder({
            buyer: msg.sender,
            usdcAmount: _usdcAmount,
            lbryAmount: lbryAmount,
            lbryAddress: _lbryAddress,
            fulfilled: false,
            lbryTxHash: "",
            timestamp: block.timestamp
        });

        // Store/update user's LBRY address
        string memory oldAddress = userLbryAddresses[msg.sender];
        userLbryAddresses[msg.sender] = _lbryAddress;

        // Track order ID
        allOrderIds.push(orderId);

        emit Purchase(
            orderId,
            msg.sender,
            _usdcAmount,
            lbryAmount,
            _lbryAddress,
            block.timestamp
        );

        if (bytes(oldAddress).length > 0 && 
            keccak256(bytes(oldAddress)) != keccak256(bytes(_lbryAddress))) {
            emit LbryAddressUpdated(msg.sender, oldAddress, _lbryAddress);
        }

        return orderId;
    }

    /**
     * @dev Mark an order as fulfilled with LBRY transaction hash
     * @param _orderId The order ID to fulfill
     * @param _lbryTxHash The LBRY transaction hash
     */
    function fulfillOrder(bytes32 _orderId, string calldata _lbryTxHash) 
        external 
        onlyOwner 
    {
        require(orders[_orderId].buyer != address(0), "Order does not exist");
        require(!orders[_orderId].fulfilled, "Order already fulfilled");
        require(bytes(_lbryTxHash).length > 0, "Transaction hash cannot be empty");

        orders[_orderId].fulfilled = true;
        orders[_orderId].lbryTxHash = _lbryTxHash;

        emit OrderFulfilled(_orderId, _lbryTxHash, block.timestamp);
    }

    /**
     * @dev Update the price of LBRY credits in USDC
     * @param _newPriceInUsdc New price in USDC (with 6 decimals)
     */
    function updatePrice(uint256 _newPriceInUsdc) external onlyOwner {
        require(_newPriceInUsdc > 0, "Price must be greater than 0");

        uint256 oldPrice = lbryPriceInUsdc;
        lbryPriceInUsdc = _newPriceInUsdc;

        emit PriceUpdated(oldPrice, _newPriceInUsdc, block.timestamp);
    }

    /**
     * @dev Withdraw USDC from the contract
     * @param _to Address to send USDC to
     * @param _amount Amount of USDC to withdraw
     */
    function withdrawUsdc(address _to, uint256 _amount) external onlyOwner {
        require(_to != address(0), "Invalid recipient address");
        require(_amount > 0, "Amount must be greater than 0");
        require(usdc.balanceOf(address(this)) >= _amount, "Insufficient balance");

        require(usdc.transfer(_to, _amount), "USDC transfer failed");
    }

    /**
     * @dev Emergency withdrawal of all USDC
     * @param _to Address to send USDC to
     */
    function emergencyWithdrawAll(address _to) external onlyOwner {
        require(_to != address(0), "Invalid recipient address");

        uint256 balance = usdc.balanceOf(address(this));
        if (balance > 0) {
            require(usdc.transfer(_to, balance), "USDC transfer failed");
        }
    }

    // View functions

    /**
     * @dev Get order details by order ID
     */
    function getOrder(bytes32 _orderId) external view returns (PurchaseOrder memory) {
        return orders[_orderId];
    }

    /**
     * @dev Get all order IDs
     */
    function getAllOrderIds() external view returns (bytes32[] memory) {
        return allOrderIds;
    }

    /**
     * @dev Get orders by buyer address
     */
    function getOrdersByBuyer(address _buyer) external view returns (bytes32[] memory) {
        uint256 count = 0;

        // First pass: count orders for this buyer
        for (uint256 i = 0; i < allOrderIds.length; i++) {
            if (orders[allOrderIds[i]].buyer == _buyer) {
                count++;
            }
        }

        // Second pass: populate array
        bytes32[] memory buyerOrders = new bytes32[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < allOrderIds.length; i++) {
            if (orders[allOrderIds[i]].buyer == _buyer) {
                buyerOrders[index] = allOrderIds[i];
                index++;
            }
        }

        return buyerOrders;
    }

    /**
     * @dev Get unfulfilled orders
     */
    function getUnfulfilledOrders() external view returns (bytes32[] memory) {
        uint256 count = 0;

        // First pass: count unfulfilled orders
        for (uint256 i = 0; i < allOrderIds.length; i++) {
            if (!orders[allOrderIds[i]].fulfilled) {
                count++;
            }
        }

        // Second pass: populate array
        bytes32[] memory unfulfilledOrders = new bytes32[](count);
        uint256 index = 0;

        for (uint256 i = 0; i < allOrderIds.length; i++) {
            if (!orders[allOrderIds[i]].fulfilled) {
                unfulfilledOrders[index] = allOrderIds[i];
                index++;
            }
        }

        return unfulfilledOrders;
    }

    /**
     * @dev Calculate LBRY amount for given USDC amount
     */
    function calculateLbryAmount(uint256 _usdcAmount) external view returns (uint256) {
        require(lbryPriceInUsdc > 0, "Price not set");
        return (_usdcAmount * 1e8) / lbryPriceInUsdc;
    }

    /**
     * @dev Get contract USDC balance
     */
    function getUsdcBalance() external view returns (uint256) {
        return usdc.balanceOf(address(this));
    }

    /**
     * @dev Get total number of orders
     */
    function getTotalOrders() external view returns (uint256) {
        return allOrderIds.length;
    }
}

